use std::sync::Arc;
use std::thread::{self, JoinHandle};
use std::time::Duration;

struct Options {
    prefix: String,
    delay: Duration,
}

fn launch(options: &Arc<Options>) -> JoinHandle<String> {
    let worker = Arc::clone(options);
    let prefix = options.prefix.clone();
    thread::spawn(move || {
        thread::sleep(worker.delay);
        format!("{prefix}:ready")
    })
}

